postgres=X/postgres,service_role=X/postgres}","body_sha256":"7e4a95085b4db167e38fbddc3c02b0edd61502c80c287c7c68fe2cf404f0d23e","definition_sha256":"9fc7ecec84dcada0860b443b3190cbc4bc93c8b6f1642dcb2e077249357b06ad"},{"schema_name":"public","function_name":"examination_room_v1_lifecycle_guard","arguments":"p_exam_id uuid","result_type":"jsonb","security_definer":true,"settings":["search_path=pg_catalog"],"owner_name":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres}","body_sha256":"2913cd1f0af99c9a7999ceb93666e3ebacaed79333d33fb3e4e6049eb75c260c","definition_sha256":"5be56ab90978ae40cdd821a7577bbe3ce977f9d6766c95fac4f111c4fbc9677b"}]$expected_functions$::jsonb
  THEN RAISE EXCEPTION 'Current function bytes/signatures/security/settings/ACL/owners differ from capture'; END IF;

  SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'owner',pg_get_userbyid(n.nspowner),'acl',n.nspacl::text) ORDER BY n.nspname)
  INTO actual FROM pg_namespace n WHERE n.nspname IN ('examination_room_v1','public','auth','extensions');
  IF actual IS DISTINCT FROM $expected_schemas$[{"acl":"{supabase_admin=UC/supabase_admin,anon=U/supabase_admin,authenticated=U/supabase_admin,service_role=U/supabase_admin,supabase_auth_admin=UC/supabase_admin,dashboard_user=UC/supabase_admin,postgres=U/supabase_admin}","owner":"supabase_admin","schema":"auth"},{"acl":"{postgres=UC/postgres,service_role=U/postgres}","owner":"postgres","schema":"examination_room_v1"},{"acl":"{postgres=UC/postgres,anon=U/postgres,authenticated=U/postgres,service_role=U/postgres,dashboard_user=UC/postgres}","owner":"postgres","schema":"extensions"},{"acl":"{pg_database_owner=UC/pg_database_owner,=U/pg_database_owner,postgres=U/pg_database_owner,anon=U/pg_database_owner,authenticated=U/pg_database_owner,service_role=U/pg_database_owner}","owner":"pg_database_owner","schema":"public"}]$expected_schemas$::jsonb
  THEN RAISE EXCEPTION 'Schema owners/ACLs differ from capture'; END IF;

  SELECT jsonb_agg(jsonb_build_object('role',rolname,'superuser',rolsuper,'inherit',rolinherit,'bypass_rls',rolbypassrls,'can_login',rolcanlogin) ORDER BY rolname)
  INTO actual FROM pg_roles WHERE rolname IN ('postgres','service_role','anon','authenticated');
  IF actual IS DISTINCT FROM $expected_roles$[{"role":"anon","inherit":true,"can_login":false,"superuser":false,"bypass_rls":false},{"role":"authenticated","inherit":true,"can_login":false,"superuser":false,"bypass_rls":false},{"role":"postgres","inherit":true,"can_login":true,"superuser":false,"bypass_rls":true},{"role":"service_role","inherit":true,"can_login":false,"superuser":false,"bypass_rls":true}]$expected_roles$::jsonb
  THEN RAISE EXCEPTION 'Exercised database role flags differ from capture'; END IF;

  SELECT jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname) ORDER BY e.extname)
  INTO actual FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname IN ('pgcrypto','plpgsql');
  IF actual IS DISTINCT FROM $expected_extensions$[{"name":"pgcrypto","schema":"extensions","version":"1.3"},{"name":"plpgsql","schema":"pg_catalog","version":"1.0"}]$expected_extensions$::jsonb
  THEN RAISE EXCEPTION 'Fixture extension versions/schemas differ from capture'; END IF;

  SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'kind',c.relkind,'column',a.attname,'type',format_type(a.atttypid,a.atttypmod)) ORDER BY n.nspname,c.relname,a.attnum)
  INTO actual FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE a.attnum>0 AND NOT a.attisdropped AND ((n.nspname='auth' AND c.relname='users') OR (n.nspname='public' AND c.relname IN ('profiles','user_roles')));
  IF actual IS DISTINCT FROM $expected_external_columns$[{"kind":"r","type":"uuid","table":"users","column":"id","schema":"auth"},{"kind":"r","type":"character varying(255)","table":"users","column":"email","schema":"auth"},{"kind":"r","type":"jsonb","table":"users","column":"raw_user_meta_data","schema":"auth"},{"kind":"r","type":"uuid","table":"profiles","column":"id","schema":"public"},{"kind":"r","type":"text","table":"profiles","column":"display_name","schema":"public"},{"kind":"r","type":"text","table":"profiles","column":"school","schema":"public"},{"kind":"r","type":"text","table":"profiles","column":"law_school_id","schema":"public"},{"kind":"r","type":"text","table":"profiles","column":"law_school_other","schema":"public"},{"kind":"r","type":"uuid","table":"user_roles","column":"user_id","schema":"public"},{"kind":"r","type":"text","table":"user_roles","column":"role","schema":"public"}]$expected_external_columns$::jsonb
  THEN RAISE EXCEPTION 'Synthetic dependency column names/types differ from capture'; END IF;
END $verify_current_capture$;
COMMIT;
SELECT 'CURRENT_CAPTURE_CATALOG_VERIFIED' AS fixture_verification;
